 modal(title,html,async fd=>{const b={action,...defaults,...Object.fromEntries(fd)};if(action==='price_table_upload'){const f=fd.get('price_file');delete b.price_file;if(!f?.size)throw Error('Selecione a tabela Excel do fornecedor.');if(f.size>5_000_000)throw Error('A planilha deve ter até 5 MB.');if((f.type&&f.type!=='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')||!f.name.toLowerCase().endsWith('.xlsx'))throw Error('Use uma planilha Excel .xlsx.');b.file_name=f.name;b.file_mime='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';b.file_data=await readFileBase64(f);}if(['work','work_update'].includes(action)){const logo=fd.get('work_logo_file');delete b.work_logo_file;b.remove_logo=fd.get('remove_logo')==='true';if(logo?.size){if(logo.size>1_000_000)throw Error('O logo do empreendimento deve ter até 1 MB.');if(!['image/png','image/jpeg'].includes(logo.type))throw Error('Use uma imagem PNG ou JPEG.');b.logo_data=await readFileBase64(logo);b.logo_mime=logo.type;}}if(action==='invoice'){const f=fd.get('invoice_attachment');delete b.invoice_attachment;if(f?.size){if(f.size>5_000_000)throw Error('Anexe um arquivo XML ou PDF de até 5 MB.');b.document_name=f.name;b.document_base64=await readFileBase64(f);}}for(const k of ['quantity','progress','stage_percent','lead_days','interval_seconds','estimated_payment_days'])if(k in b)b[k]=Number(b[k]);for(const k of ['cents','unit_cents','freight_cents','total_value','amount_value','opening_balance_value'])if(k in b)b[k]=Math.round(Number(b[k])*100);if('total_value'in b){b.total_cents=b.total_value;delete b.total_value;}if('amount_value'in b){b.amount_cents=b.amount_value;delete b.amount_value;}if('opening_balance_value'in b){b.opening_balance_cents=b.opening_balance_value;delete b.opening_balance_value;}if(action==='cashflow_edit')b.action='cashflow_event';for(const k of ['qualified','whatsapp_optin','commercial_optin','financial_optin','active'])if(k in b)b[k]=b[k]==='true';if(action==='rfq')b.request_ids=fd.getAll('request_ids');if(['work','work_update'].includes(action)&&$('#same-address')?.checked)for(const part of ['postal_code','street','number','complement','district','city','uf'])b['delivery_'+part]=b['site_'+part];await api('operate',b);});
 if(action==='invoice')$('#form [name="request_id"]').onchange=e=>{const req=state.requests.find(x=>x.id===e.target.value),quote=req&&state.quotes.find(q=>q.id===req.selected_quote);$('#form [name="supplier_id"]').value=quote?.supplier_id||'';};
 if(['work','work_update'].includes(action))$('#same-address').onchange=event=>{for(const part of ['postal_code','street','number','complement','district','city','uf']){const source=$('#form [name="site_'+part+'"]'),target=$('#form [name="delivery_'+part+'"]');if(event.target.checked)target.value=source.value;if(target.tagName==='SELECT')target.disabled=event.target.checked;else target.readOnly=event.target.checked;}};
 if(action==='item'){const input=$('#form [name="product_id"]');if(input){input.required=false;input.onchange=()=>{const p=state.products.find(p=>p.id===input.value);for(const name of ['name','unit'])$('#form [name="'+name+'"]').readOnly=!!p;if(p){$('#form [name="name"]').value=p.name;$('#form [name="unit"]').value=p.unit;$('#form [name="lead_days"]').value=p.lead_days;}};}}
