function compare(rid){const r=state.requests.find(r=>r.id===rid),q=state.quotes.filter(q=>q.request_id===rid).sort((a,b)=>(a.unit_cents*r.quantity+a.freight_cents)-(b.unit_cents*r.quantity+b.freight_cents));modal('Comparar cotações',`<div class="wide">${q.map(q=>`<div class="row"><div><strong>${esc(supplierBy(q.supplier_id)?.name)}</strong><p>${money(Math.round(q.unit_cents*r.quantity)+q.freight_cents)} · ${q.lead_days} dias</p><p class="muted">Frete ${money(q.freight_cents)} · Validade ${fmt(q.valid_until)}<br>${esc(q.terms)}</p></div>${r.status==='cotacao'&&can('approve')?`<button type="button" data-approve="${q.id}" class="primary">Aprovar</button>`:''}</div>`).join('')}</div>`,null);document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('operate',{action:'approve',quote_id:b.dataset.approve});$('#modal').close();notice('Cotação aprovada e saldo reservado.');await refresh();}catch(e){$('#form-error').textContent=e.message;b.disabled=false;}});}
function send(rfqId,channel){const rfq=state.rfqs.find(r=>r.id===rfqId),supplier=supplierBy(rfq.supplier_id);modal('Enviar cotação por '+channel,`<p class="wide">Enviar o PDF dos itens selecionados para <strong>${esc(supplier.contact||supplier.name)}</strong>, em ${esc(channel==='email'?supplier.email:supplier.phone)}. O disparo será registrado.</p>`,async()=>api('dispatch',{rfq_id:rfqId,channel}));}
async function refresh(){if(busy||!user)return;busy=true;try{state=await api('state');refreshTime=new Date().toLocaleTimeString('pt-BR');if(!$('#modal').open)render();}catch(e){notice(e.message);}finally{busy=false;}}
async function init(){const s=await api('session');user=s.user;if(user){await refresh();return;}$('#app').innerHTML=`<div class="login"><h1>JRC Compras</h1><p>${s.needs_setup?'Configure o administrador para começar a planejar sua primeira obra.':'Entre para acompanhar as compras da obra.'}</p><form id="login">${s.needs_setup?'<label>Nome<input name="name" required></label>':''}<label>E-mail<input type="email" name="email" required autocomplete="username"></label><label>Senha<input type="password" name="password" required minlength="${s.needs_setup?12:1}" maxlength="128" autocomplete="${s.needs_setup?'new-password':'current-password'}"></label>${s.needs_setup?'<label>Token de instalação (somente VPS)<input name="setup_token" type="password"></label>':''}<p id="login-error" class="danger"></p><button class="primary">${s.needs_setup?'Criar administrador':'Entrar'}</button></form></div>`;$('#login').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api(s.needs_setup?'setup':'login',Object.fromEntries(new FormData(e.target)));await init();}catch(error){$('#login-error').textContent=error.message;}finally{b.disabled=false;}};}
init().catch(e=>notice(e.message));setInterval(()=>{if(user&&!document.hidden&&!$('#modal').open)refresh();},15000);
function renderInvoices(){
 const invoices=(state.invoices||[]).filter(n=>{const req=state.requests.find(x=>x.id===n.request_id),item=req&&itemBy(req.item_id);return !workId||item?.work_id===workId;});
 const invoiceRows=invoices.map(n=>{const req=state.requests.find(x=>x.id===n.request_id),item=req&&itemBy(req.item_id);return `<tr><td><strong>${esc(n.invoice_number)}</strong><span class="muted">Emissão ${fmt(n.issue_date)} · Recebida ${fmt(n.received_date)}<br>Vencimento ${fmt(n.due_date)}${n.access_key?'<br>Chave '+esc(n.access_key):''}</span></td><td>${esc(req?.order_number)}<span class="muted">${esc(workBy(item?.work_id)?.name)} · ${esc(item?.name)}</span></td><td>${esc(supplierBy(n.supplier_id)?.name)}</td><td>${money(n.total_cents)}</td><td>${tag(n.status==='paga'?'Paga':'Em aberto',n.status==='aberta'&&n.due_date<nowDay())}</td><td>${n.status==='aberta'&&can('invoice')?`<button data-invoice-paid="${n.id}">Registrar pagamento</button>`:''}</td></tr>`;});
 const inbox=(state.qiveInbox||[]).filter(n=>!n.imported_invoice_id&&(!workId||state.works.some(w=>w.id===workId&&w.profile?.cnpj?.replace(/\\D/g,'')===n.receiver_cnpj))).map(n=>`<tr><td><strong>NF ${esc(n.number)}</strong><span class="muted">${esc(n.access_key)}<br>Emitida ${fmt(n.issue_date)}</span></td><td>${esc(n.emitter_name)}<span class="muted">CNPJ ${esc(n.emitter_cnpj)}</span></td><td>${esc(n.receiver_cnpj)}</td><td>${n.total_cents?money(n.total_cents):'Conferir XML / valor'}</td><td>${tag(n.status,n.status==='canceled')}</td><td>${n.status==='authorized'&&can('invoice')?`<button data-qive-link="${esc(n.access_key)}">Vincular ao pedido</button>`:'—'}</td></tr>`);
 $('#content').innerHTML=`<section class="panel"><h2>Integração Arquivei / Qive</h2><p>${state.qive.configured?tag('API configurada'):tag('Aguardando credenciais API',true)} · Consulta automática: a cada ${state.qive.intervalSeconds} segundos.</p><p class="muted">Última consulta: ${state.qive.lastSync?fmt(state.qive.lastSync):'ainda não realizada'}${state.qive.lastError?'<br>Falha mais recente: '+esc(state.qive.lastError):''}</p><p class="muted">A busca é limitada aos CNPJs/SPEs cadastrados em Configurações &gt; Obras. Documentos de outros destinatários ficam fora do sistema de compras.</p><div class="actions">${can('qive_config')?'<button data-qive-config>Configurar intervalo</button>':''}${can('qive_sync')?`<button data-qive-sync ${state.qive.configured?'':'disabled'}>Sincronizar agora</button>`:''}<a class="button" href="/api/invoices/export">Exportar NFs Excel</a><a class="button" href="/api/invoices/template">Baixar modelo Excel</a>${can('invoice')?'<button data-invoice-import>Importar NFs em massa</button>':''}</div></section><h2 style="margin-top:24px">Notas fiscais registradas</h2>${table(['NF / vencimento','Pedido / obra','Fornecedor','Valor','Situação','Ação'],invoiceRows)}<h2 style="margin-top:24px">Notas recebidas pela Qive aguardando vínculo</h2>${table(['Documento / emissão','Fornecedor da NF','CNPJ destinatário (SPE)','Valor informado','Situação','Ação'],inbox)}`;
}
